BEGIN;
-- Journal Lines Part 2 of 2

-- Step 5: Recalculate all account balances
UPDATE accounts SET current_balance = COALESCE(sub.balance, 0)
FROM (
  SELECT a.id,
    SUM(
      CASE 
        WHEN a.account_type IN ('asset', 'expense') THEN (COALESCE(jl.debit_amount::numeric, 0) - COALESCE(jl.credit_amount::numeric, 0))
        ELSE (COALESCE(jl.credit_amount::numeric, 0) - COALESCE(jl.debit_amount::numeric, 0))
      END
    ) as balance
  FROM accounts a
  LEFT JOIN journal_lines jl ON jl.account_id = a.id
  LEFT JOIN journal_entries je ON je.id = jl.journal_entry_id AND je.is_posted = true
  GROUP BY a.id
) sub
WHERE accounts.id = sub.id;
COMMIT;
